INSERT INTO posts VALUES(499,1,'🏆 End of Season Processing Complete',replace('\n        <p><strong>📊 End of Season League Update</strong></p>\n        <p>The league has successfully completed end of season processing:</p>\n        <ul>\n        <li><strong>💰 Salary Bills:</strong> Processed for 8 human clubs and 125 CPU clubs</li>\n        <li><strong>👴 Player Ages:</strong> All 5183 players aged by 1 year</li>\n        <li><strong>📜 Contracts:</strong> 3699 players had contracts reduced by 1 year</li>\n        <li><strong>💵 Salaries:</strong> All 3699 players had salaries doubled</li>\n        <li><strong>📈 Wage Rises:</strong> 5183 players had yearly wage rises applied</li>\n        <li><strong>🎯 Skill Development:</strong> 5183 players had their skills developed (total change: +130728 points)</li>\n        <li><strong>👋 Player Retirements:</strong> 52 players retired from the league</li>\n        <li><strong>🌟 New Talent:</strong> 0 new young players (16-18 years old) joined to replace retirees</li>\n        </ul>\n        <p><strong>✅ The new season is ready to begin!</strong></p>\n        <p>All clubs have settled their financial obligations, player contracts have been updated, skills have evolved, veterans have retired, and fresh talent has entered the league for the upcoming season.</p>\n        ','\n',char(10)),'none',NULL,'2025-09-24T20:24:39.504996');
INSERT INTO posts VALUES(500,1,'💰 League Market Value Recalculation Complete',replace('\n            <p><strong>📊 League Market Value Update</strong></p>\n            <p>The league has completed a comprehensive market value recalculation for all players (salaries remain unchanged).</p>\n            <ul>\n            <li><strong>✅ Players Updated:</strong> 3690</li>\n            <li><strong>❌ Errors:</strong> 0</li>\n            <li><strong>🚫 Excluded:</strong> No Club players (market value set to €0)</li>\n            </ul>\n            <p><strong>🏆 Top 5 Most Valuable Players by Position:</strong></p><h6>Unknown</h6><ul><li>1. Rooney (Unknown): €200,688,921</li><li>2. C. Ronaldo (Unknown): €190,982,608</li><li>3. Ronaldinho (Unknown): €164,231,117</li><li>4. Martins (Unknown): €140,395,704</li><li>5. Adriano (Unknown): €117,255,732</li></ul>\n            <p><strong>📈 What was recalculated:</strong></p>\n            <ul>\n            <li>Market values based on current salaries and age multipliers</li>\n            <li>Age-based market value adjustments</li>\n            <li>No Club players automatically set to €0 market value</li>\n            </ul>\n            <p><strong>💡 Note:</strong> Player salaries remain unchanged to maintain financial stability.</p>\n            ','\n',char(10)),'none',NULL,'2025-09-24T20:28:31.968830');
