PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE users (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    username TEXT UNIQUE NOT NULL,
    password TEXT NOT NULL,
    email TEXT UNIQUE NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE posts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    title TEXT NOT NULL,
    content TEXT NOT NULL,
    media_type TEXT DEFAULT 'none',
    media_path TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE comments (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    post_id INTEGER NOT NULL,
    user_id INTEGER NOT NULL,
    content TEXT NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (post_id) REFERENCES posts(id) ON DELETE CASCADE,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE teams (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    club_name TEXT UNIQUE NOT NULL
, total_salaries INTEGER DEFAULT 0, budget INTEGER DEFAULT 0, available_cap INTEGER DEFAULT 0, stance TEXT DEFAULT 'Tinkering');
CREATE TABLE players (
    id INTEGER PRIMARY KEY, -- Use INTEGER PRIMARY KEY for autoincrement in SQLite
    player_name TEXT NOT NULL,
    shirt_name TEXT,
    club_id INTEGER,
    registered_position TEXT,
    age INTEGER,
    height INTEGER,
    weight INTEGER,
    nationality TEXT,
    strong_foot TEXT,
    favoured_side TEXT,
    gk INTEGER DEFAULT 0,
    cwp INTEGER DEFAULT 0,
    cbt INTEGER DEFAULT 0,
    sb INTEGER DEFAULT 0,
    dmf INTEGER DEFAULT 0,
    wb INTEGER DEFAULT 0,
    cmf INTEGER DEFAULT 0,
    smf INTEGER DEFAULT 0,
    amf INTEGER DEFAULT 0,
    wf INTEGER DEFAULT 0,
    ss INTEGER DEFAULT 0,
    cf INTEGER DEFAULT 0,
    attack INTEGER,
    defense INTEGER,
    balance INTEGER,
    stamina INTEGER,
    top_speed INTEGER,
    acceleration INTEGER,
    response INTEGER,
    agility INTEGER,
    dribble_accuracy INTEGER,
    dribble_speed INTEGER,
    short_pass_accuracy INTEGER,
    short_pass_speed INTEGER,
    long_pass_accuracy INTEGER,
    long_pass_speed INTEGER,
    shot_accuracy INTEGER,
    shot_power INTEGER,
    shot_technique INTEGER,
    free_kick_accuracy INTEGER,
    swerve INTEGER,
    heading INTEGER,
    jump INTEGER,
    technique INTEGER,
    aggression INTEGER,
    mentality INTEGER,
    goal_keeping INTEGER,
    team_work INTEGER,
    consistency INTEGER,
    condition_fitness INTEGER,
    dribbling_skill INTEGER DEFAULT 0,
    tactical_dribble INTEGER DEFAULT 0,
    positioning INTEGER DEFAULT 0,
    reaction INTEGER DEFAULT 0,
    playmaking INTEGER DEFAULT 0,
    passing INTEGER DEFAULT 0,
    scoring INTEGER DEFAULT 0,
    one_one_scoring INTEGER DEFAULT 0,
    post_player INTEGER DEFAULT 0,
    lines INTEGER DEFAULT 0,
    middle_shooting INTEGER DEFAULT 0,
    side INTEGER DEFAULT 0,
    centre INTEGER DEFAULT 0,
    penalties INTEGER DEFAULT 0,
    one_touch_pass INTEGER DEFAULT 0,
    outside INTEGER DEFAULT 0,
    marking INTEGER DEFAULT 0,
    sliding INTEGER DEFAULT 0,
    covering INTEGER DEFAULT 0,
    d_line_control INTEGER DEFAULT 0,
    penalty_stopper INTEGER DEFAULT 0,
    one_on_one_stopper INTEGER DEFAULT 0,
    long_throw INTEGER DEFAULT 0,
    injury_tolerance TEXT,
    dribble_style INTEGER,
    free_kick_style INTEGER,
    pk_style INTEGER,
    drop_kick_style INTEGER,
    skin_color INTEGER,
    face_type INTEGER,
    preset_face_number INTEGER,
    head_width INTEGER,
    neck_length INTEGER,
    neck_width INTEGER,
    shoulder_height INTEGER,
    shoulder_width INTEGER,
    chest_measurement INTEGER,
    waist_circumference INTEGER,
    arm_circumference INTEGER,
    leg_circumference INTEGER,
    calf_circumference INTEGER,
    leg_length INTEGER,
    wristband TEXT,
    wristband_color TEXT,
    international_number INTEGER,
    classic_number INTEGER,
    club_number INTEGER,
    salary INTEGER DEFAULT 0,
    contract_years_remaining INTEGER DEFAULT 0,
    market_value INTEGER DEFAULT 0,
    yearly_wage_rise INTEGER DEFAULT 0,
    -- Bundled skill areas for better player display
    attack_rating INTEGER DEFAULT 0,
    defense_rating INTEGER DEFAULT 0,
    physical_rating INTEGER DEFAULT 0,
    power_rating INTEGER DEFAULT 0,
    technique_rating INTEGER DEFAULT 0,
                goalkeeping_rating INTEGER DEFAULT 0,
            game_position TEXT DEFAULT '', development_key INTEGER DEFAULT 0, trait_key INTEGER DEFAULT 0, overall INTEGER DEFAULT 0, games_played INTEGER DEFAULT 0, goals INTEGER DEFAULT 0, assists INTEGER DEFAULT 0, career_earnings INTEGER DEFAULT 0, championships_won INTEGER DEFAULT 0, cups_won INTEGER DEFAULT 0, loaned_by TEXT DEFAULT NULL,
            FOREIGN KEY (club_id) REFERENCES teams(id)
);
/****** CORRUPTION ERROR *******/
CREATE TABLE player_performance (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    player_id INTEGER,
    season TEXT,
    matches_played INTEGER,
    goals INTEGER,
    assists INTEGER,
    FOREIGN KEY (player_id) REFERENCES players(id) ON DELETE CASCADE
);
CREATE TABLE league_teams (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    team_name TEXT UNIQUE NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    budget INTEGER DEFAULT 450000000,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE team_players (
    team_id INTEGER NOT NULL,
    player_id INTEGER NOT NULL,
    PRIMARY KEY (team_id, player_id),
    FOREIGN KEY (team_id) REFERENCES league_teams(id) ON DELETE CASCADE,
    FOREIGN KEY (player_id) REFERENCES players(id) ON DELETE CASCADE
);
CREATE TABLE messages (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    sender_id INTEGER NOT NULL,
    receiver_id INTEGER NOT NULL,
    subject TEXT,
    content TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (sender_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (receiver_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE offers (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    sender_id INTEGER NOT NULL,
    receiver_id INTEGER NOT NULL,
    player_id INTEGER NOT NULL,
    offer_amount INTEGER NOT NULL,
    offered_players TEXT,
    offered_money INTEGER DEFAULT 0,
    requested_players TEXT,
    requested_money INTEGER DEFAULT 0,
    sender_team_id INTEGER,
    receiver_team_id INTEGER,
    status TEXT DEFAULT 'pending',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (sender_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (receiver_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (player_id) REFERENCES players(id) ON DELETE CASCADE,
    FOREIGN KEY (sender_team_id) REFERENCES league_teams(id) ON DELETE CASCADE,
    FOREIGN KEY (receiver_team_id) REFERENCES league_teams(id) ON DELETE CASCADE
);
CREATE TABLE blacklist (
    user_id INTEGER NOT NULL,
    player_id INTEGER NOT NULL,
    PRIMARY KEY (user_id, player_id),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (player_id) REFERENCES players(id) ON DELETE CASCADE
);
CREATE TABLE free_agent_offers (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    player_id INTEGER NOT NULL,
    user_id INTEGER NOT NULL,
    offered_salary INTEGER NOT NULL,
    offered_contract_years INTEGER NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    expires_at TIMESTAMP NOT NULL,
    status TEXT DEFAULT 'active',
    FOREIGN KEY (player_id) REFERENCES players(id) ON DELETE CASCADE,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE user_budgets (
    user_id INTEGER PRIMARY KEY,
    budget INTEGER DEFAULT 450000000,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE user_movements (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    type TEXT NOT NULL,
    description TEXT NOT NULL,
    amount INTEGER NOT NULL,
    balance_after INTEGER NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE cpu_league_seasons (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    season_name TEXT NOT NULL,
                    status TEXT NOT NULL DEFAULT 'not_started',
                    current_round INTEGER DEFAULT 0,
                    max_rounds INTEGER DEFAULT 0,
                    division_count INTEGER DEFAULT 4,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    completed_at TIMESTAMP NULL
                );
CREATE TABLE cpu_league_divisions (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    season_id INTEGER NOT NULL,
                    division_number INTEGER NOT NULL,
                    team_id INTEGER NOT NULL,
                    team_name TEXT NOT NULL,
                    games_played INTEGER DEFAULT 0,
                    wins INTEGER DEFAULT 0,
                    losses INTEGER DEFAULT 0,
                    goals_for INTEGER DEFAULT 0,
                    goals_against INTEGER DEFAULT 0,
                    points INTEGER DEFAULT 0,
                    FOREIGN KEY (season_id) REFERENCES cpu_league_seasons(id),
                    FOREIGN KEY (team_id) REFERENCES teams(id),
                    UNIQUE(season_id, division_number, team_id)
                );
CREATE TABLE cpu_league_matches (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    season_id INTEGER NOT NULL,
                    division_number INTEGER NOT NULL,
                    round_number INTEGER NOT NULL,
                    home_team_id INTEGER NOT NULL,
                    away_team_id INTEGER NOT NULL,
                    home_score INTEGER DEFAULT 0,
                    away_score INTEGER DEFAULT 0,
                    played BOOLEAN DEFAULT FALSE,
                    played_at TIMESTAMP NULL,
                    FOREIGN KEY (season_id) REFERENCES cpu_league_seasons(id),
                    FOREIGN KEY (home_team_id) REFERENCES teams(id),
                    FOREIGN KEY (away_team_id) REFERENCES teams(id)
                );
CREATE TABLE cpu_league_scorers (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    match_id INTEGER NOT NULL,
                    player_id INTEGER NOT NULL,
                    team_id INTEGER NOT NULL,
                    minute INTEGER NOT NULL,
                    is_goal BOOLEAN DEFAULT TRUE,
                    is_assist BOOLEAN DEFAULT FALSE,
                    FOREIGN KEY (match_id) REFERENCES cpu_league_matches(id),
                    FOREIGN KEY (player_id) REFERENCES players(id),
                    FOREIGN KEY (team_id) REFERENCES teams(id)
                );
CREATE TABLE league_seasons (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    season_name TEXT NOT NULL UNIQUE,
                    is_current BOOLEAN DEFAULT FALSE,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE player_season_history (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    player_id INTEGER NOT NULL,
                    season TEXT NOT NULL,
                    club_id INTEGER,
                    club_name TEXT,
                    games_played INTEGER DEFAULT 0,
                    goals INTEGER DEFAULT 0,
                    assists INTEGER DEFAULT 0,
                    salary INTEGER DEFAULT 0,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (player_id) REFERENCES players(id),
                    FOREIGN KEY (club_id) REFERENCES teams(id),
                    UNIQUE(player_id, season)
                );
CREATE TABLE blog_posts (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    title TEXT NOT NULL,
                    content TEXT NOT NULL,
                    author_id INTEGER NOT NULL,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (author_id) REFERENCES users (id)
                );
CREATE TABLE retired_players (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    player_id INTEGER NOT NULL,
                    player_name TEXT NOT NULL,
                    team_name TEXT,
                    age_at_retirement INTEGER,
                    nationality TEXT,
                    registered_position TEXT,
                    retirement_date TEXT DEFAULT CURRENT_TIMESTAMP,
                    retirement_season TEXT,
                    career_earnings INTEGER DEFAULT 0,
                    total_games_played INTEGER DEFAULT 0,
                    total_goals INTEGER DEFAULT 0,
                    total_assists INTEGER DEFAULT 0,
                    final_salary INTEGER DEFAULT 0,
                    final_market_value INTEGER DEFAULT 0,
                    retirement_reason TEXT,
                    seasons_played INTEGER DEFAULT 0,
                    championships_won INTEGER DEFAULT 0,
                    cups_won INTEGER DEFAULT 0,
                    FOREIGN KEY (player_id) REFERENCES players(id)
                );
CREATE TABLE market_bazaar_listings (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    player_id INTEGER NOT NULL,
                    team_id INTEGER NOT NULL,
                    asking_price INTEGER NOT NULL,
                    expires_at TEXT NOT NULL,
                    status TEXT DEFAULT 'active',
                    listing_type TEXT DEFAULT 'user_sale',
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (player_id) REFERENCES players (id),
                    FOREIGN KEY (team_id) REFERENCES teams (id)
                );
CREATE TABLE market_bazaar_offers (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    listing_id INTEGER NOT NULL,
                    buyer_team_id INTEGER NOT NULL,
                    offered_price INTEGER NOT NULL,
                    expires_at TEXT NOT NULL,
                    status TEXT DEFAULT 'active',
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (listing_id) REFERENCES market_bazaar_listings (id),
                    FOREIGN KEY (buyer_team_id) REFERENCES teams (id)
                );
CREATE TABLE user_cpu_offers (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    buyer_team_id INTEGER NOT NULL,
                    seller_team_id INTEGER NOT NULL,
                    player_id INTEGER NOT NULL,
                    offered_price INTEGER NOT NULL,
                    status TEXT DEFAULT 'pending',
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (buyer_team_id) REFERENCES league_teams (id),
                    FOREIGN KEY (seller_team_id) REFERENCES teams (id),
                    FOREIGN KEY (player_id) REFERENCES players (id)
                );
CREATE TABLE app_settings (
                    key TEXT PRIMARY KEY,
                    value TEXT NOT NULL,
                    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                );
